import json

with open('diff.txt') as f:
    lines = f.readlines()[:200]
    diff = ''.join(lines)

prompt = (
    'あなたは日本人英語学習者のための親切な英語コーチです。'
    '以下のgit diffの追加行（+で始まる行）を添削してください。'
    '回答はすべて日本語で行ってください。\n\n'
    '以下のルールに従ってください：\n'
    '1. 英語がすでに自然で正しい場合は、最初にその旨を明確に伝えてください（例：「この表現は自然です✅」）。\n'
    '2. 問題がある場合は、なぜ問題なのかを日本語で簡潔に説明し、改善案を提示してください。\n'
    '3. 添削の後（問題がない場合も）、より洗練されたネイティブらしい表現を1つだけ提案し、簡単な説明を加えてください。\n'
    '4. 回答は簡潔にまとめてください。\n\n'
    '差分:\n' + diff
)

payload = {
    'contents': [{
        'parts': [{
            'text': prompt
        }]
    }]
}

print(json.dumps(payload))